<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue';
import {Button,Input} from '@openclaw-plugins/control-ui-kit';
import {type Skill,type Provider,type Policy,type Confirmation,type Action,states,time,summary,skillState,providerStatus} from './maintenance-model';
import MaintenanceFields from './MaintenanceFields.vue';
const props=defineProps<{skill?:Skill;provider?:Provider;rows:Skill[];tab:string;safe:(v:unknown)=>string;writable:boolean;busy:boolean;loading:boolean;retry:boolean;confirmation:Confirmation|null;policy:Policy}>();
const emit=defineEmits<{choose:[kind:'skill'|'cli',key:string];back:[];tab:[value:string];confirm:[action:Action,settings?:Policy];execute:[action:Action];cancel:[];export:[];policy:[value:Policy]}>();
const title=ref<HTMLElement>(),confirmButton=ref<InstanceType<typeof Button>>();
const p=computed(()=>props.provider),skill=computed(()=>props.skill),disabled=computed(()=>props.busy||props.loading||props.retry||!props.writable||!p.value?.revision);
const tabs=computed(()=>[['overview','概览'],...(!skill.value?[['settings','更新设置']]:[]),...(p.value?[['history','维护记录']]:[]),['diagnostic','诊断']]);
const settingsAction=computed(()=>p.value?.actions?.find(a=>a.settings));
function policyField(key:keyof Policy,value:unknown){emit('policy',{...props.policy,[key]:value});}
const diagnostic=computed<[string,unknown][]>(()=>skill.value&&!skill.value.provider?[['路径',skill.value.path],['提交',skill.value.updatedCommit],['更新时间',time(skill.value.updatedAt)],['适用条件',skill.value.appliesWhen],['覆盖来源',skill.value.overriddenBy],['禁用原因',skill.value.disabledReason]]:(p.value?.fields??[]).map(f=>[f.label,f.value]));
watch(()=>props.confirmation,async value=>{if(value){await nextTick();(confirmButton.value?.$el as HTMLElement)?.focus();}});
watch([()=>props.skill?.key,()=>props.provider?.id],async()=>{await nextTick();title.value?.focus({preventScroll:true});},{immediate:true});
</script>
<template><aside class="ar-maintenance-detail" :aria-label="skill?'技能详情':'CLI 详情'"><header><h3 ref="title" tabindex="-1">{{safe(skill?.label??p?.label)}}</h3><Button variant="ghost" @click="emit('back')">返回列表</Button></header><p class="ar-description">{{safe(skill?.sourceLabel??p?.ownerLabel??p?.label)}}</p><nav class="ar-maintenance-detail-tabs" aria-label="详情视图"><Button v-for="[key,label] in tabs" :key="key" variant="ghost" :aria-current="tab===key?'page':undefined" @click="emit('tab',key!)">{{label}}</Button></nav>
<template v-if="tab==='settings'&&p"><p v-if="!settingsAction" class="ar-muted">此提供方未开放更新设置。</p><template v-else><p class="ar-maintenance-scope">{{safe(p.scope)}}</p><form v-if="confirmation?.providerId!==p.id" class="ar-maintenance-settings" @submit.prevent="emit('confirm',settingsAction,{...policy,version:policy.version.trim(),updateCheckIntervalHours:Number(policy.updateCheckIntervalHours)})"><label class="ar-maintenance-switch"><input type="checkbox" :checked="policy.autoUpdate" aria-label="自动更新 CLI 与配套技能" :disabled="disabled" @change="policyField('autoUpdate',($event.target as HTMLInputElement).checked)"/><span>自动更新 CLI 与配套技能</span></label><label><span>固定版本</span><Input :model-value="policy.version" aria-label="固定版本" placeholder="留空跟随兼容稳定版" :disabled="disabled" @update:model-value="policyField('version',String($event))"/></label><label><span>检查间隔（小时）</span><Input :model-value="policy.updateCheckIntervalHours" aria-label="检查间隔（小时）" type="number" min="1" max="720" required :disabled="disabled" @update:model-value="policyField('updateCheckIntervalHours',Number($event))"/></label><p class="ar-muted">固定版本优先于自动更新；自动更新默认开启。</p><Button type="submit" :disabled="disabled">保存更新设置</Button></form></template></template>
<template v-else-if="tab==='history'&&p"><h4>维护记录</h4><p v-if="!p.history?.length" class="ar-muted">暂无维护记录。</p><article v-for="operation in p.history??[]" :key="operation.id" class="ar-maintenance-event"><strong>{{states[operation.status]??operation.status}}</strong><p>{{safe((p.actions?.find(a=>a.id===operation.action)?.label??operation.action)+' · '+time(operation.createdAt))}}</p><small>{{safe([operation.actorAgentId?'来源 Agent '+operation.actorAgentId:null,operation.finishedAt?'结束于 '+time(operation.finishedAt):null,operation.errorCode].filter(Boolean).join(' · '))}}</small><p v-if="operation.status==='unknown'" class="ar-warning">操作可能已执行，请核查当前状态；不会自动重放。</p></article></template>
<template v-else-if="tab==='diagnostic'"><MaintenanceFields :entries="diagnostic" :safe="safe"/><details v-if="p?.body"><summary>查看已提交技能正文</summary><pre>{{safe(p.body)}}</pre><p v-if="p.bodyTruncated">正文预览达到上限。</p></details><Button variant="outline" @click="emit('export')">导出脱敏诊断</Button></template>
<template v-else-if="skill"><MaintenanceFields :entries="[['当前状态',skillState(skill)],['适用范围',skill.scope||'当前仓库范围']]" :safe="safe"/><h4>用途与使用条件</h4><p class="ar-maintenance-description">{{safe(skill.description||'此技能尚未提供用途说明。')}}</p><p v-if="skill.warning||skill.disabledReason" class="ar-warning">{{safe(skill.disabledReason??skill.warning)}}</p><template v-if="skill.cli"><h4>关联 CLI</h4><div class="ar-maintenance-dependency">{{safe(skill.cli.label)}}<small>{{safe(skill.cli.scope)}}</small></div><MaintenanceFields :entries="[['当前版本',skill.cli.versions?.current],['更新状态',providerStatus(skill.cli)],['自动更新',skill.cli.policy?.autoUpdate?'已开启':'已关闭']]" :safe="safe"/><Button @click="emit('choose','cli',skill.cli.id)">查看 CLI 详情</Button></template><template v-else-if="p"><p class="ar-muted">由 AgentRepo 自动生成，供 Worker 按任务读取；版本通知不代表实际读取。</p><Button v-for="action in p.actions??[]" :key="action.id" :disabled="disabled" @click="emit('confirm',action)">{{action.label}}</Button></template><p v-else class="ar-muted">当前来源没有声明受托管的 CLI 依赖；不会根据技能名称推断安装状态。</p></template>
<template v-else-if="p"><p class="ar-maintenance-scope">{{safe(p.scope)}}</p><h4>版本信息</h4><strong class="ar-maintenance-status">{{providerStatus(p)}}</strong><MaintenanceFields class="ar-maintenance-versions" :entries="[['当前版本',p.versions?.current],['可更新版本',p.versions?.available??'尚未检查']]" :safe="safe"/><p class="ar-muted">更新由提供方执行，关联技能索引与 CLI 一同维护。</p><h4>自动更新设置</h4><MaintenanceFields :entries="[['当前状态',p.policy?p.policy.autoUpdate?'开启':'关闭':'未提供'],['固定版本',p.policy?.version||'跟随兼容稳定版'],['检查间隔',p.policy?p.policy.updateCheckIntervalHours+' 小时':'未提供']]" :safe="safe"/><Button v-if="settingsAction" variant="outline" @click="emit('tab','settings')">修改设置</Button><footer class="ar-maintenance-actions"><template v-for="action in p.actions??[]" :key="action.id"><Button v-if="!action.settings&&action.id!=='rollback'" :disabled="disabled" @click="action.id==='check'?emit('execute',action):emit('confirm',action)">{{action.id==='update'&&p.versions?.available?'更新至 '+p.versions.available:action.label}}</Button></template><details v-if="p.actions?.some(a=>a.id==='rollback')"><summary>更多操作</summary><Button v-for="action in p.actions.filter(a=>a.id==='rollback')" :key="action.id" :disabled="disabled" @click="emit('confirm',action)">{{action.label}}</Button></details></footer><details class="ar-maintenance-associations"><summary>关联技能（{{p.skills?.length??0}}）</summary><Button v-for="associated in p.skills??[]" :key="associated.name" class="ar-maintenance-linked-skill ocp:h-auto ocp:whitespace-normal" variant="ghost" @click="emit('choose','skill',rows.find(r=>r.provider===p&&r.name===associated.name)!.key)">{{associated.name}}<small v-if="associated.description">{{safe(summary(associated.description))}}</small></Button></details></template>
<section v-if="p&&confirmation?.providerId===p.id" class="ar-maintenance-confirm" aria-label="确认维护操作"><h4>{{confirmation.action.id==='configure'?'确认保存更新设置':confirmation.action.label}}</h4><p class="ar-maintenance-scope">{{safe(p.scope)}}</p><p v-if="confirmation.action.effect">{{safe(confirmation.action.effect)}}</p><MaintenanceFields v-if="confirmation.settings" :entries="[['自动更新',confirmation.settings.autoUpdate?'开启':'关闭'],['固定版本',confirmation.settings.version||'跟随兼容稳定版'],['检查间隔',confirmation.settings.updateCheckIntervalHours+' 小时']]" :safe="safe"/><MaintenanceFields v-else-if="confirmation.action.id==='update'" :entries="[['当前版本',p.versions?.current],['目标版本',p.policy?.version??p.versions?.available??'检查后选择兼容稳定版']]" :safe="safe"/><Button ref="confirmButton" :disabled="busy||!writable||retry" @click="emit('execute',confirmation.action)">确认执行</Button><Button variant="outline" :disabled="busy" @click="emit('cancel')">取消</Button></section>
</aside></template>
